    { key: "cells", label: "Grid cells", min: 32, max: 320, step: 2, default: 140 },
    { key: "levels", label: "Tone steps", min: 2, max: 8, step: 1, default: 3 },
    { key: "scale", label: "Wave scale", min: 0.3, max: 12, step: 0.1, default: 1.5 },
